import{_ as s,a0 as a,w as i,s as l,ao as u,I as r,x as p,a1 as e,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"在Ubuntu中使用終端刪除應用程序 | LCTT x X-CMD","titleTemplate":false,"description":"在Ubuntu中使用終端刪除應用程序 | LCTT (201309) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在Ubuntu中使用終端刪除應用程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在Ubuntu中使用終端刪除應用程序 | LCTT (201309) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201309/Removing Applications Using Terminal in Ubuntu","title":"在Ubuntu中使用終端刪除應用程序","tag":"201309","desc":""},"relativePath":"201309/Removing Applications Using Terminal in Ubuntu.md","filePath":"[post].md"}'),d={name:"201309/Removing Applications Using Terminal in Ubuntu.md"};function g(m,t,c,T,x,b){const n=a("Link");return i(),l("div",null,[t[11]||(t[11]=u(`<h1 id="在ubuntu中使用終端刪除應用程序" tabindex="-1">在Ubuntu中使用終端刪除應用程序 <a class="header-anchor" href="#在ubuntu中使用終端刪除應用程序" aria-label="Permalink to “在Ubuntu中使用終端刪除應用程序”">​</a></h1><p>作為一個Linux（Ubuntu)用户，你每次從終端安裝應用程序的時候都會用到<strong>apt-get</strong>這條命令。</p><p>雖然可以使用圖形化界面來安裝刪除應用程序，但是命令列依然被認為是功能強大的方式。在安裝了許多大大小小的應用程序以後，你會需要更多的磁盤空間來安裝其他的應用程序，或者有些程序對你不再有用了。</p><p>大多數人，尤其是初學者，通過在查閲資料後，能夠從終端安裝一個程序，但是卻很難刪除它。我也曾經有過這樣的經歷。</p><p>這是一個簡單的教程，指導你如何刪除已經安裝的軟件包。</p><p>a. 打開終端（ctrl + alt + t）</p><p>b. 輸入</p><pre><code>$ dpkg --list
</code></pre><p>（這條命令會顯示所有已安裝的包）</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/09/list_.png" alt=""></p><p>或者</p><pre><code>$ dpkg --list | less
</code></pre><p>（這樣可以輕鬆的使用用户密鑰來導航）</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/09/dpkg_list.png" alt=""></p><p>或者</p><p>如果你知道軟件包的名字，你可以使用管道命令<strong>grep</strong>來查找，使用下面的語句：</p><pre><code>$ dpkg --list|grep -i  &#39;packagename&#39;
</code></pre><p>以<strong>VLC</strong>播放器為例。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/09/vlc_grep.png" alt=""></p><p>c. 查找要刪除的包名字，這裏我要使用<strong>sox</strong>。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/09/remove_SoX.png" alt=""></p><p>d. 只刪除一個軟件包，使用下面的命令：</p><pre><code>$ sudo apt-get remove &lt;packagename&gt;
</code></pre><p>比如，刪除一個叫<strong>sox</strong>的軟件包，輸入：</p><pre><code>$ sudo apt-get remove sox
</code></pre><p>輸入y來確認卸載。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/09/sox2.png" alt=""></p><p>e. 要刪除一個包以及它的配置文件，輸入：</p><pre><code>$ sudo apt-get --purge remove &lt;packagename&gt;
</code></pre><p>比如，刪除一個叫sox的包以及其所有的配置文件：</p><pre><code>$ sudo apt-get --purge remove sox
</code></pre>`,31)),r("p",null,[t[1]||(t[1]=p("via: ",-1)),e(n,{href:"http://www.unixmen.com/removing-applications-using-terminal-ubuntu/"},{default:o(()=>[...t[0]||(t[0]=[p("http://www.unixmen.com/removing-applications-using-terminal-ubuntu/",-1)])]),_:1})]),r("p",null,[t[4]||(t[4]=p("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[2]||(t[2]=[p("LCTT",-1)])]),_:1}),t[5]||(t[5]=p(" 原創翻譯，",-1)),e(n,{href:"http://linux.cn/portal.php"},{default:o(()=>[...t[3]||(t[3]=[p("Linux中國",-1)])]),_:1}),t[6]||(t[6]=p(" 榮譽推出",-1))]),r("p",null,[t[9]||(t[9]=p("譯者：",-1)),e(n,{href:"http://linux.cn/space/markvv"},{default:o(()=>[...t[7]||(t[7]=[p("markvv",-1)])]),_:1}),t[10]||(t[10]=p(" 校對：",-1)),e(n,{href:"http://linux.cn/space/14763"},{default:o(()=>[...t[8]||(t[8]=[p("Caroline",-1)])]),_:1})])])}const U=s(d,[["render",g]]);export{C as __pageData,U as default};
